    'property.unpublished', 'property', p_property_id,
    jsonb_build_object(
      'property_id', p_property_id,
      'slug', v_after.slug,
      'market', v_after.market_slug,
      'reason', p_reason,
      'takedown', p_takedown
    ),
    p_actor
  );
  return jsonb_build_object('event_id', v_event, 'version', v_after.version);
end;
$$;

